  const at = (t, v) => toks[p].t === t && (v === undefined || toks[p].v === v);
  const atKw = (v) => toks[p].t === 'NAME' && toks[p].v === v;
  const eat = (t, v) => at(t, v) ? toks[p++] : null;
  const eatKw = (v) => atKw(v) ? toks[p++] : null;
